1	import { db } from "@/lib/db";
2	import type { Invoice, InvoiceStatus, Prisma, User } from "@prisma/client";
3	
4	/**
5	 * Invoice line item shape stored in `Invoice.lineItems` (Json).
6	 * Amounts are integer cents. `amountCents` is authoritative; qty * unitCents
7	 * is used as a fallback when a line omits it.
8	 */
9	export type LineItem = {
10	  description: string;
11	  qty: number;
12	  unitCents: number;
13	  amountCents: number;
14	};
15	
16	export function coerceLineItems(raw: unknown): LineItem[] {
17	  if (!Array.isArray(raw)) return [];
18	  return raw
19	    .filter((x): x is Record<string, unknown> => !!x && typeof x === "object")
20	    .map((x) => {
21	      const qty = Number(x.qty ?? 1) || 0;
22	      const unitCents = Math.round(Number(x.unitCents ?? 0) || 0);
23	      const amountCents = Math.round(
24	        Number(x.amountCents ?? qty * unitCents) || 0
25	      );
26	      return {
27	        description: String(x.description ?? "Item"),
28	        qty,
29	        unitCents,
30	        amountCents,
31	      };
32	    });
33	}
34	
35	/** Compute subtotal / tax / total (all integer cents) for an invoice. */
36	export function invoiceTotals(invoice: Pick<Invoice, "lineItems" | "taxCents" | "amountCents">) {
37	  const items = coerceLineItems(invoice.lineItems);
38	  const subtotalCents = items.reduce((sum, li) => sum + li.amountCents, 0);
39	  const taxCents = invoice.taxCents ?? 0;
40	  // `amountCents` is the stored authoritative total; fall back to computed.
41	  const totalCents = invoice.amountCents ?? subtotalCents + taxCents;
42	  return { items, subtotalCents, taxCents, totalCents };
43	}
44	
45	const STATUS_LABEL: Record<InvoiceStatus, string> = {
46	  OPEN: "Open",
47	  PAID: "Paid",
48	  VOID: "Void",
49	  REFUNDED: "Refunded",
50	};
51	
52	export function invoiceStatusLabel(status: InvoiceStatus): string {
53	  return STATUS_LABEL[status] ?? status;
54	}
55	
56	export type InvoiceInput = {
57	  userId: string;
58	  description: string;
59	  lineItems: LineItem[];
60	  taxCents?: number;
61	  status?: InvoiceStatus;
62	  period?: { start?: Date | null; end?: Date | null };
63	};
64	
65	/**
66	 * Build the `data` payload for an Invoice row WITHOUT touching the database, so
67	 * a charge site can create the invoice inside its own guarded `$transaction`
68	 * (sharing the charge's idempotency guard) via `tx.invoice.create({ data })`.
69	 * The stored total (`amountCents`) is always derived from line items + tax so
70	 * callers can't desync the stamped total from the itemised breakdown.
71	 */
72	export function invoiceCreateData(opts: InvoiceInput): Prisma.InvoiceUncheckedCreateInput {
73	  const items = opts.lineItems.map((li) => ({
74	    description: String(li.description),
75	    qty: Number(li.qty) || 0,
76	    unitCents: Math.round(Number(li.unitCents) || 0),
77	    amountCents: Math.round(
78	      Number(li.amountCents ?? (Number(li.qty) || 0) * (Number(li.unitCents) || 0)) || 0
79	    ),
80	  }));
81	  const taxCents = Math.round(opts.taxCents ?? 0);
82	  const subtotalCents = items.reduce((s, li) => s + li.amountCents, 0);
83	  const amountCents = subtotalCents + taxCents;
84	  const status = opts.status ?? "OPEN";
85	
86	  return {
87	    userId: opts.userId,
88	    description: opts.description,
89	    lineItems: items,
90	    taxCents,
91	    amountCents,
92	    status,
93	    paidAt: status === "PAID" ? new Date() : null,
94	    periodStart: opts.period?.start ?? null,
95	    periodEnd: opts.period?.end ?? null,
96	  };
97	}
98	
99	/**
100	 * Create an Invoice row directly. The total (`amountCents`) is derived from the
101	 * line items plus tax so callers can't accidentally desync the stamped total
102	 * from the itemised breakdown.
103	 */
104	export async function createInvoice(opts: InvoiceInput): Promise<Invoice> {
105	  return db.invoice.create({ data: invoiceCreateData(opts) });
106	}
107	
108	function esc(s: unknown): string {
109	  return String(s ?? "")
110	    .replace(/&/g, "&amp;")
111	    .replace(/</g, "&lt;")
112	    .replace(/>/g, "&gt;")
113	    .replace(/"/g, "&quot;");
114	}
115	
116	function money(cents: number): string {
117	  const neg = cents < 0;
118	  return `${neg ? "−" : ""}$${(Math.abs(cents) / 100).toFixed(2)}`;
119	}
120	
121	function fmtDate(d: Date | null | undefined): string {
122	  if (!d) return "—";
123	  return new Date(d).toLocaleDateString("en-US", {
124	    year: "numeric",
125	    month: "short",
126	    day: "numeric",
127	  });
128	}
129	
130	const STATUS_STAMP: Record<InvoiceStatus, { color: string; label: string }> = {
131	  PAID: { color: "#10b981", label: "PAID" },
132	  OPEN: { color: "#f59e0b", label: "OPEN" },
133	  VOID: { color: "#64748b", label: "VOID" },
134	  REFUNDED: { color: "#8a70fb", label: "REFUNDED" },
135	};
136	
137	/**
138	 * Render a clean, print-ready branded HTML invoice. Intended to be served
139	 * standalone (users Print → Save as PDF — see the download route).
140	 */
141	export function renderInvoiceHTML(
142	  invoice: Invoice,
143	  user: Pick<User, "name" | "email">
144	): string {
145	  const { items, subtotalCents, taxCents, totalCents } = invoiceTotals(invoice);
146	  const stamp = STATUS_STAMP[invoice.status] ?? STATUS_STAMP.OPEN;
147	  const number = String(invoice.number).padStart(5, "0");
148	  const period =
149	    invoice.periodStart || invoice.periodEnd
150	      ? `${fmtDate(invoice.periodStart)} – ${fmtDate(invoice.periodEnd)}`
151	      : null;
152	
153	  const rows = items
154	    .map(
155	      (li) => `
156	      <tr>
157	        <td class="desc">${esc(li.description)}</td>
158	        <td class="num">${esc(li.qty)}</td>
159	        <td class="num">${money(li.unitCents)}</td>
160	        <td class="num">${money(li.amountCents)}</td>
161	      </tr>`
162	    )
163	    .join("");
164	
165	  const logo = `
166	    <svg width="34" height="34" viewBox="0 0 40 40" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
167	      <defs>
168	        <linearGradient id="nxg" x1="0" y1="0" x2="40" y2="40" gradientUnits="userSpaceOnUse">
169	          <stop stop-color="#3b82f6"/>
170	          <stop offset="1" stop-color="#6f47f5"/>
171	        </linearGradient>
172	      </defs>
173	      <rect width="40" height="40" rx="10" fill="url(#nxg)"/>
174	      <path d="M11 28V12h3.2l9.4 10.6V12H27v16h-3.2L14.4 17.4V28H11Z" fill="#fff"/>
175	    </svg>`;
176	
177	  return `<!doctype html>
178	<html lang="en">
179	<head>
180	<meta charset="utf-8"/>
181	<meta name="viewport" content="width=device-width, initial-scale=1"/>
182	<title>Nxeon Invoice #${number}</title>
183	<style>
184	  :root { color-scheme: light; }
185	  * { box-sizing: border-box; }
186	  body {
187	    margin: 0;
188	    background: #f1f5f9;
189	    color: #0f172a;
190	    font-family: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
191	    font-size: 14px;
192	    line-height: 1.5;
193	    -webkit-print-color-adjust: exact;
194	    print-color-adjust: exact;
195	  }
196	  .sheet {
197	    max-width: 760px;
198	    margin: 32px auto;
199	    background: #fff;
200	    border-radius: 16px;
201	    box-shadow: 0 10px 40px rgba(15, 23, 42, 0.08);
202	    overflow: hidden;
203	  }
204	  .bar {
205	    height: 6px;
206	    background: linear-gradient(90deg, #3b82f6, #6f47f5);
207	  }
208	  .inner { padding: 40px; }
209	  .top { display: flex; justify-content: space-between; align-items: flex-start; gap: 24px; }
210	  .brand { display: flex; align-items: center; gap: 12px; }
211	  .brand .name { font-size: 20px; font-weight: 800; letter-spacing: -0.02em; }
212	  .brand .tag { font-size: 12px; color: #64748b; }
213	  .meta { text-align: right; }
214	  .meta .no { font-size: 13px; color: #64748b; }
215	  .meta .num { font-size: 22px; font-weight: 800; letter-spacing: -0.02em; }
216	  .stamp {
217	    display: inline-block;
218	    margin-top: 8px;
219	    padding: 4px 12px;
220	    border: 2px solid ${stamp.color};
221	    color: ${stamp.color};
222	    border-radius: 8px;
223	    font-weight: 800;
224	    font-size: 13px;
225	    letter-spacing: 0.08em;
226	    text-transform: uppercase;
227	  }
228	  .parties { display: flex; gap: 40px; margin-top: 32px; flex-wrap: wrap; }
229	  .party { min-width: 200px; }
230	  .label { font-size: 11px; text-transform: uppercase; letter-spacing: 0.08em; color: #94a3b8; font-weight: 700; margin-bottom: 6px; }
231	  .party .val { font-weight: 600; }
232	  .party .sub { color: #64748b; font-size: 13px; }
233	  table { width: 100%; border-collapse: collapse; margin-top: 32px; }
234	  thead th {
235	    text-align: left;
236	    font-size: 11px;
237	    text-transform: uppercase;
238	    letter-spacing: 0.06em;
239	    color: #94a3b8;
240	    font-weight: 700;
241	    padding: 0 0 10px;
242	    border-bottom: 1px solid #e2e8f0;
243	  }
244	  thead th.num, td.num { text-align: right; }
245	  tbody td { padding: 12px 0; border-bottom: 1px solid #f1f5f9; vertical-align: top; }
246	  td.desc { font-weight: 500; }
247	  td.num { font-variant-numeric: tabular-nums; white-space: nowrap; }
248	  .totals { margin-top: 20px; display: flex; justify-content: flex-end; }
249	  .totals table { width: 280px; margin: 0; }
250	  .totals td { border: none; padding: 6px 0; }
251	  .totals .k { color: #64748b; }
252	  .totals .v { text-align: right; font-variant-numeric: tabular-nums; }
253	  .totals .grand td { border-top: 2px solid #0f172a; padding-top: 12px; font-size: 18px; font-weight: 800; }
254	  .foot { margin-top: 40px; padding-top: 20px; border-top: 1px solid #e2e8f0; color: #94a3b8; font-size: 12px; display: flex; justify-content: space-between; gap: 16px; flex-wrap: wrap; }
255	  .print-btn {
256	    position: fixed; top: 20px; right: 20px;
257	    background: linear-gradient(90deg, #3b82f6, #6f47f5);
258	    color: #fff; border: none; border-radius: 10px;
259	    padding: 10px 18px; font-size: 13px; font-weight: 600; cursor: pointer;
260	    box-shadow: 0 6px 20px rgba(111, 71, 245, 0.35);
261	  }
262	  @media print {
263	    body { background: #fff; }
264	    .sheet { box-shadow: none; margin: 0; max-width: none; border-radius: 0; }
265	    .print-btn { display: none; }
266	  }
267	</style>
268	</head>
269	<body>
270	  <button class="print-btn" onclick="window.print()">Print / Save as PDF</button>
271	  <div class="sheet">
272	    <div class="bar"></div>
273	    <div class="inner">
274	      <div class="top">
275	        <div>
276	          <div class="brand">
277	            ${logo}
278	            <div>
279	              <div class="name">Nxeon</div>
280	              <div class="tag">Cloud VPS Hosting</div>
281	            </div>
282	          </div>
283	        </div>
284	        <div class="meta">
285	          <div class="no">Invoice</div>
286	          <div class="num">#${number}</div>
287	          <div class="stamp">${stamp.label}</div>
288	        </div>
289	      </div>
290	
291	      <div class="parties">
292	        <div class="party">
293	          <div class="label">Billed to</div>
294	          <div class="val">${esc(user.name)}</div>
295	          <div class="sub">${esc(user.email)}</div>
296	        </div>
297	        <div class="party">
298	          <div class="label">Issued</div>
299	          <div class="val">${fmtDate(invoice.createdAt)}</div>
300	          ${invoice.paidAt ? `<div class="sub">Paid ${fmtDate(invoice.paidAt)}</div>` : ""}
301	        </div>
302	        ${
303	          period
304	            ? `<div class="party"><div class="label">Service period</div><div class="val">${esc(period)}</div></div>`
305	            : ""
306	        }
307	      </div>
308	
309	      <table>
310	        <thead>
311	          <tr>
312	            <th>Description</th>
313	            <th class="num">Qty</th>
314	            <th class="num">Unit</th>
315	            <th class="num">Amount</th>
316	          </tr>
317	        </thead>
318	        <tbody>
319	          ${rows || `<tr><td class="desc" colspan="4">${esc(invoice.description)}</td></tr>`}
320	        </tbody>
321	      </table>
322	
323	      <div class="totals">
324	        <table>
325	          <tr><td class="k">Subtotal</td><td class="v">${money(subtotalCents)}</td></tr>
326	          <tr><td class="k">Tax</td><td class="v">${money(taxCents)}</td></tr>
327	          <tr class="grand"><td>Total</td><td class="v">${money(totalCents)}</td></tr>
328	        </table>
329	      </div>
330	
331	      <div class="foot">
332	        <div>${esc(invoice.description)}</div>
333	        <div>Nxeon · Thank you for your business</div>
334	      </div>
335	    </div>
336	  </div>
337	</body>
338	</html>`;
339	}
