234	      if (!Number.isFinite(n)) return { error: `“${f.key}” must be a number.` };
235	      // Refuse rather than clamp, so the stored row always equals what the operator
236	      // can read back off the field. Silent clamping is how a panel ends up showing
237	      // one number while the platform enforces another.
238	      if (f.min !== undefined && n < f.min) {
239	        return { error: `“${f.key}” must be at least ${f.min} (you entered ${s}).` };
240	      }
241	      if (f.max !== undefined && n > f.max) {
242	        return { error: `“${f.key}” must be ${f.max} or less (you entered ${s}).` };
243	      }
244	      changes.push({ key: f.key, value: f.type === "int" ? String(Math.round(n)) : String(n) });
245	      continue;
246	    }
247	
248	    changes.push({ key: f.key, value: (raw ?? "").toString().trim() });
249	  }
250	
251	  // Cross-field: the dunning schedule must run in the order the panel's own hints
252	  // promise — grace (dunning starts) ≤ warn (final-warning email) < terminate (VM
253	  // destroyed). Field-level bounds cannot catch an inverted schedule, and an
254	  // inverted one deletes a customer's server before, or without, warning them.
255	  // worker/billing.ts also clamps on read; this check exists so the operator is
256	  // TOLD, instead of having their numbers silently rewritten behind the panel.
257	  if (section === "billing") {
258	    const day = (k: string) => Number(changes.find((c) => c.key === k)?.value);
259	    const grace = day("dunning_grace_days");
260	    const warn = day("dunning_warn_days");
261	    const terminate = day("dunning_terminate_days");
262	    if (warn < grace) {
263	      return { error: `Dunning warn (${warn}d) cannot come before dunning grace (${grace}d).` };
264	    }
265	    if (terminate <= warn) {
266	      return { error: `Dunning terminate (${terminate}d) must come after the final warning (${warn}d).` };
267	    }
268	  }
269	
270	  if (changes.length === 0) return { ok: true };
271	
272	  await db.$transaction(
273	    changes.map((c) =>
274	      db.setting.upsert({ where: { key: c.key }, update: { value: c.value }, create: { key: c.key, value: c.value } }),
275	    ),
276	  );
277	
278	  await db.auditLog.create({
279	    data: {
280	      userId: user.id,
281	      action: "settings.save",
282	      detail: `${section}: ${changes.map((c) => c.key).join(", ")}`,
283	    },
284	  });
285	
286	  revalidatePath("/admin/settings");
287	  return { ok: true };
288	}
