74	export function DeployWizard({
75	  plans, images, nodes, sshKeys, isAdmin, balanceCents, dedicatedIpAvailable, dedicatedIpPriceCents,
76	  extraDiskPriceCentsPerGb = 0,
77	  promoPercent = 0, promoLabel,
78	}: {
79	  plans: Plan[]; images: Image[]; nodes: NodeOpt[];
80	  sshKeys: { id: string; name: string }[]; isAdmin: boolean; balanceCents: number;
81	  dedicatedIpAvailable?: boolean; dedicatedIpPriceCents?: number;
82	  /**
83	   * Price per GB per month for extra ROOT DISK (admin setting
84	   * `extra_disk_gb_price_cents`). Priced over the term exactly like the dedicated
85	   * IP add-on, so the maths here matches lib/order.ts orderQuote byte-for-byte.
86	   * 0 hides the upsell entirely.
87	   */
88	  extraDiskPriceCentsPerGb?: number;
89	  /** Active intro-promo discount (%) on the FIRST term — matches what payAndDeploy charges. */
90	  promoPercent?: number; promoLabel?: string;
91	}) {
92	  const [state, action, pending] = useActionState(payAndDeploy, {} as { error?: string; checkoutUrl?: string });
93	  // Apply the first-term promo to any regular price, mirroring promoPriceCents()
94	  // in lib/promotions.ts so the wizard's displayed price === the checkout charge.
95	  const hasPromo = promoPercent > 0;
96	  const promoCents = (regular: number) => Math.round(regular * (1 - promoPercent / 100));
97	  // Only redirect to Stripe as the result of an EXPLICIT Deploy submit. The flag is
98	  // armed in the Deploy button's onClick (and the Enter-on-final-step path) and
99	  // consumed here, so a stale `checkoutUrl` in state can never redirect on its own —
100	  // e.g. after a back-button remount (ref starts false) or an unrelated re-render.
101	  const submittedRef = useRef(false);
102	  useEffect(() => {
103	    if (state?.checkoutUrl && submittedRef.current) {
104	      submittedRef.current = false;
105	      window.location.href = state.checkoutUrl;
106	    }
107	  }, [state]);
108	  const multiNode = nodes.length > 1;
109	  const steps = ["Plan", ...(multiNode ? ["Location"] : []), "Install", "Add-ons", "Access", "Review"];
110	  const [step, setStep] = useState(0);
111	
112	  const [planId, setPlanId] = useState(plans[0]?.id ?? "");
113	  const [nodeId, setNodeId] = useState(nodes[0]?.id ?? "");
114	  const [imageId, setImageId] = useState(images.find((i) => i.category === "PLAIN_OS")?.id ?? images[0]?.id ?? "");
115	  const [tab, setTab] = useState<string>("os");
116	  const [modalFamily, setModalFamily] = useState<string | null>(null);
117	  const [q, setQ] = useState("");
118	  const [addons, setAddons] = useState({ malware: false, backup: false, docker: false });
119	  const [dedicatedIp, setDedicatedIp] = useState(false);
120	  // Extra ROOT DISK bought up front. One-way: this space can never be removed
121	  // later, which the Add-ons card and the Review step both state before payment.
122	  const [extraDiskGB, setExtraDiskGB] = useState(0);
123	  const [hostname, setHostname] = useState("");
124	  const [rootPw, setRootPw] = useState("");
125	  const [pubKey, setPubKey] = useState("");
126	  const [free, setFree] = useState(false);
127	  const [termMonths, setTermMonths] = useState(1);
128	  // Apply the wallet balance by default whenever there's something to apply.

