192	/**
193	 * Every setting, with defaults merged under any stored overrides. Secret values
194	 * ARE included — callers that hand this to the client (the settings page) must
195	 * strip SECRET_KEYS themselves.
196	 */
197	export async function getAllSettings(): Promise<Record<string, string>> {
198	  const rows = await db.setting.findMany();
199	  const merged: Record<string, string> = { ...SETTINGS_DEFAULTS };
200	  for (const r of rows) merged[r.key] = r.value;
201	  return merged;
202	}
203	
204	/**
205	 * The admin-configured default billing term, in MONTHS, guaranteed to be a term the
206	 * platform can actually sell.
207	 *
208	 * The guarantee is the point. `default_term` was previously the enum
209	 * "monthly"|"quarterly"|"annual" and the platform's real terms are 1/12/24/36 months
210	 * (`VPS_TERMS`) — "quarterly" mapped to nothing at all. Anything stored that
211	 * `VPS_TERMS` does not contain (a legacy row, or a hand-crafted POST that slipped past
212	 * the panel's enum check) falls back to the first term rather than pre-selecting a
213	 * commitment no charge path can price. A wizard that pre-selects an unsellable term
214	 * would fail at `vpsTerm()`'s own silent `?? VPS_TERMS[0]` fallback, charging monthly
215	 * while the review step displayed something else.
216	 */
217	export async function defaultTermMonths(): Promise<number> {
218	  const months = Number(await getSetting("default_term"));
219	  return VPS_TERMS.some((t) => t.months === months) ? months : VPS_TERMS[0].months;
220	}
221	
222	/**
223	 * The public support address, guaranteed non-empty.
224	 *
225	 * Shared rather than inlined because it is rendered into `mailto:` hrefs on the public
226	 * contact page. `saveSettings` happily stores a blank string when an operator clears the
227	 * field, and `mailto:` with no recipient opens an empty compose window — a visitor who
228	 * clicks "Email our team" would be left with nowhere to send it and no error to explain
229	 * why. The hardcoded default is the address the marketing site has always published.
230	 */
231	export async function supportEmail(): Promise<string> {
232	  const v = (await getSetting("support_email")).trim();
233	  return v || SETTINGS_DEFAULTS.support_email;
234	}

